#!/bin/sh
# Captures the outdoor kit's validation views from the developer fixture.
#
# The fixture level is generated by tools/levels/build_outdoor_fixture.py and
# compiled with places-compile; this script stages the package into its own
# scratch state root and captures a fixed view set, so two runs (or two
# quality profiles) are directly comparable:
#
#     python3 tools/levels/build_outdoor_fixture.py
#     cargo run --release --bin places-compile -- build \
#         tests/fixtures/levels/outdoor_kit_showcase.json \
#         --out target/outdoor-kit/outdoor_kit_showcase.placesmap
#     sh tools/bench/capture_outdoor_kit.sh
#     PLACES_QUALITY=low sh tools/bench/capture_outdoor_kit.sh
#
# Environment:
#   PLACES_BIN            executable to capture (default target/release/places)
#   PLACES_CAPTURE_DIR    output root (default target/agent-work/outdoor-kit-captures)
#   PLACES_QUALITY        `high` (default) or `low`, named in the file suffix
#   PLACES_KIT_PACKAGE    compiled fixture package
#                         (default target/outdoor-kit/outdoor_kit_showcase.placesmap)
set -eu

REPO=$(cd "$(dirname "$0")/../.." && pwd)
BIN="${PLACES_BIN:-$REPO/target/release/places}"
OUT="${PLACES_CAPTURE_DIR:-$REPO/target/agent-work/outdoor-kit-captures}"
STATE="${PLACES_KIT_STATE:-$REPO/target/outdoor-kit-state}"
PACKAGE="${PLACES_KIT_PACKAGE:-$REPO/target/outdoor-kit/outdoor_kit_showcase.placesmap}"
PROFILE="${PLACES_QUALITY:-high}"

if [ ! -x "$BIN" ]; then
    echo "capture_outdoor_kit: $BIN is not executable; run 'cargo build --release' first" >&2
    exit 1
fi
if [ ! -f "$PACKAGE" ]; then
    echo "capture_outdoor_kit: $PACKAGE is missing; compile the fixture first" >&2
    exit 1
fi

case "$PROFILE" in
    low) filtering=low; lightmaps=off; reflections=off ;;
    medium) filtering=medium; lightmaps=medium; reflections=medium ;;
    high | full) filtering=high; lightmaps=full; reflections=full ;;
    *)
        echo "capture_outdoor_kit: PLACES_QUALITY must be 'low', 'medium' or 'high'" >&2
        exit 2
        ;;
esac

mkdir -p "$STATE/levels" "$OUT/$PROFILE"
cp "$PACKAGE" "$STATE/levels/outdoor_kit_showcase.placesmap"
cat > "$STATE/settings.json" <<JSON
{
  "bindings": {
    "forward": "W", "backward": "S", "strafe_left": "A", "strafe_right": "D",
    "look_up": "UP", "look_down": "DOWN", "look_left": "LEFT", "look_right": "RIGHT"
  },
  "look_speed_h": 90.0, "look_speed_v": 60.0, "walk_speed": 3.0, "fov_degrees": 60.0,
  "invert_look": false, "vsync": false, "texture_filtering": "$filtering",
  "quality": "$PROFILE", "bloom": true, "reflections": "$reflections",
  "lightmaps": "$lightmaps", "window_mode": "windowed", "window_width": 640, "window_height": 360
}
JSON

# One line per view: <name>:<spawn x,z[,yaw] or x,y,z,yaw>:<camera yaw,pitch>
VIEWS="
arrival:10.0,16.0,0::
path_to_door:10.0,13.0,0:0,-4:
path_edge_near:8.6,8.0,0:0,-28:
path_edge_grazing:10.9,8.0,270:270,-5:
path_end:10.0,18.2,0:0,-32:
grass_low:16.0,4.5,0:0,-14:
grass_medium:4.0,12.0,90:90,-14:
grass_dense:6.4,6.6,0:0,-18:
tree:5.5,10.5,0:0,10:
stand_lamp:9.0,9.5,347:347,-12:
fence_lamp:3.0,10.0,299:299,-10:
facade:10.0,9.0,0:0,-2:
doorway:10.0,4.2,0:0,2:
eave_lamps:10.0,5.0,0:0,12:
sky_open:10.0,12.0,0:0,42:
shed_inside:28.5,8.6,90:90,0:
shed_out:28.5,8.6,90:270,0:
kit_house_01:13.2,11.0,0:180,6:
kit_house_02:13.4,11.4,0:150,6:
kit_house_03:20.4,11.0,0:180,6:
kit_house_04:18.6,13.4,0:0,6:
kit_house_05:22.2,13.4,0:0,6:
kit_window_side:8.0,17.4,0:90,6:
kit_roofs:13.2,9.0,0:180,20:
kit_trees:11.5,13.4,0:262,8:
kit_streetlight:12.6,2.6,0:180,10:
kit_railing:25.0,13.6,0:210,0:
kit_yard:13.0,12.4,0:96,4:
"

failures=0
: > "$OUT/$PROFILE/manifest.txt"
for view in $VIEWS; do
    name="${view%%:*}"
    rest="${view#*:}"
    spawn="${rest%%:*}"
    camera="${rest#*:}"
    camera="${camera%:}"
    set -- env PLACES_STATE_ROOT="$STATE" PLACES_BENCH=1 PLACES_BENCH_NOSWAP=1 \
        PLACES_LEVEL=outdoor_kit_showcase PLACES_QUALITY="$PROFILE"
    if [ -n "$spawn" ]; then
        set -- "$@" PLACES_SPAWN="$spawn"
    fi
    if [ -n "$camera" ]; then
        set -- "$@" PLACES_CAMERA="$camera"
    fi
    set -- "$@" PLACES_CAPTURE="$OUT/$PROFILE/${name}.png" "$BIN"
    if "$@" >/dev/null 2>&1; then
        printf '%s\tlevel=outdoor_kit_showcase\tspawn=%s\tcamera=%s\tquality=%s\n' \
            "${name}.png" "${spawn:-<level-spawn>}" "${camera:-<spawn-yaw>}" "$PROFILE" \
            >> "$OUT/$PROFILE/manifest.txt"
    else
        echo "FAILED ${PROFILE}/${name}" >&2
        failures=$((failures + 1))
    fi
done

captured=$(wc -l < "$OUT/$PROFILE/manifest.txt" | tr -d ' ')
echo "capture_outdoor_kit: $OUT/$PROFILE: $captured captured, $failures failed"
[ "$failures" -eq 0 ]
